    self._durationOfStroking  = checkNumber(MaidCoffeeUtils.GetMaidCoffeeManagerSettingVo(MaidCoffeeConstants.ParamsIds.DurationOfStroking).num)

    -- self._recoveryInterval = 20
    ---每X秒恢复一点心情值
    self._onePointInterval    = checkInt(self._recoveryInterval / self._recoverMoodValue)
    ---休息室能显示的卡牌数据（只保存 MaidCoffeeConstants.CafeStatus.Non 和 CafeStatus.Resting）
    self._cards               = nil

    self._loungeInfo          = nil
    self._playerCardId2Info   = nil
    self._playerCardId2RecoveryValue = nil
    
end

