function OverManegeLoungeDataProvider:HandleResponseFeed(data, playerCardId, snackId, interface, isStroke)
    self:UpdateRecoveryValue(playerCardId, data.cafeEnergy)
    
    local snackList = self._snackList
    for i, v in ipairs(snackList) do
        if v.goodsId == snackId then
            snackList[i].goodsNum = snackList[i].goodsNum - 1 
            break
        end
    end
    
    GoodsUtils.DrawRewards({{goodsId = snackId, num = -1}})
    
    if not self:CheckCardShowCond(cardComp:GetCardById(playerCardId)) then
        self:RemoveCardById(playerCardId)
    end
    Events.Broadcast(MaidCoffeeConstants.EventNames.LoungeCardEnergyTimeChange, true)
    Events.Broadcast(MaidCoffeeConstants.EventNames.LoungeRequestSuccess, interface, {[playerCardId] = true}, isStroke)
end

