function OverManegeLoungeDataProvider:HandleResponseFeedAll(data, roomId, interface, isStroke)
    local snackList = self._snackList
    local goodsId2Data = {}
    for k, v in pairs(snackList) do
        goodsId2Data[checkNumber(v.goodsId)] = v
    end

    
    local foodConsumes = data.consume
    local consumes     = {}
    for foodType, foodData in pairs(foodConsumes) do
        local num     = foodData.num
        local goodsId = checkNumber(foodData.goodsId)
        local data = goodsId2Data[goodsId]
        if data then
            data.goodsNum = data.goodsNum - num
        end
        foodData.num = num * -1
        table.insert(consumes, foodData)
    end
    
    GoodsUtils.DrawRewards(consumes)

    local cardsEnergyInfo = data.cardsEnergyInfo
    local t = {}
    for index, value in pairs(cardsEnergyInfo) do
        local playerCardId = checkNumber(value.playerCardId)
        t[playerCardId] = true
        self:UpdateRecoveryValue(playerCardId, value.cafeEnergy) 
        if not self:CheckCardShowCond(cardComp:GetCardById(playerCardId)) then
            self:RemoveCardById(playerCardId)
        end
    end

    Events.Broadcast(MaidCoffeeConstants.EventNames.LoungeCardEnergyTimeChange, true)
    Events.Broadcast(MaidCoffeeConstants.EventNames.LoungeRequestSuccess, interface, t, isStroke)

end

