--region init

---InitHomeData_
---初始化休息室home 数据
---@param data table 接口数据 
---[view online](http://117.186.215.226:8888/wangnan/cat-doc/-/blob/master/%E6%8E%A5%E5%8F%A3%E6%96%87%E6%A1%A3/overseaCafe.md#overseacafeloungehome-%E4%BC%91%E6%81%AF%E5%AE%A4%E9%A6%96%E9%A1%B5)
function OverManegeLoungeDataProvider:InitHomeData_(data)
    self:InitCardsInfo(data)

    ---------------------------------
    --- 初始化休息室 能使用的食物

    local snacks = GoodsConfMgr:GetInstance():GetExpGoodsVoList(Constants.GoodsEffectType.MaidCoffSnack)
    local snackList = {}
    for _, vo in pairs(snacks) do
        local goodsId  = vo.id
        local goodsNum = GoodsUtils.GetThingNo(goodsId)
        table.insert(snackList, {goodsId = goodsId, vo = vo, goodsNum = goodsNum})
    end
    
    self._snackList                  = snackList
    
end

function OverManegeLoungeDataProvider:InitCardsInfo(data)
    local rooms           = data.rooms
    local cardsEnergyInfo = data.cardsEnergyInfo

    ---------------------------------
    --- 初始化休息室数据
    local nextCureSeconds
    local playerCardId2Info          = {}
    local playerCardId2RecoveryValue = {}
    for i, v in ipairs(cardsEnergyInfo) do
        local playerCardId = checkNumber(v.playerCardId)

        ---@type CardDojo
        local cardDojo   = cardComp:GetCardById(playerCardId)
        cardDojo:UpdateCafeStatus(MaidCoffeeConstants.CafeStatus.Resting)
        
        local cafeEnergy = checkInt(v.cafeEnergy)
        --- 更新下卡牌现在的心情
        cardDojo:UpdateCardEnergy(cafeEnergy,true)
        nextCureSeconds = checkNumber(v.nextCureSeconds)
        
        local cardInfo, recoveryValue = self:CreateLoungeCardData_(playerCardId, checkNumber(v.nextCureSeconds), checkNumber(v.touchTimes))
        playerCardId2Info[playerCardId]          = cardInfo
        playerCardId2RecoveryValue[playerCardId] = recoveryValue
        
    end
    Events.Broadcast("MaidCoff.ChangeCardEnergy")
    local maxLoungeCount = 0
    local loungeInfo      = {}
    local loungeStatus
    local LoungeStatus = MaidCoffeeConstants.LoungeStatus
    for i, roomData in pairs(rooms) do
        local roomId = checkNumber(roomData.roomId)
        ---@type MaidCoffeeClerkSettingVo
        local vo = MaidCoffeeUtils.GetMaidCoffeeClerkSettingVo(roomId)
        local unlocked = checkNumber(roomData.unlocked) == 1
        local vip      = (vo ~= nil and checkNumber(vo.vip) or 0) == 1 

        if vip then
            loungeStatus = unlocked and LoungeStatus.VipUnlock or LoungeStatus.VipLock
        else
            loungeStatus = unlocked and LoungeStatus.Unlock    or LoungeStatus.Lock
        end

        local cards         = roomData.cards
        local playerCardIds, cardCount = self:ParamsCards(cards)

        local data = {
            vip           = vip,
            roomId        = roomId,
            playerCardIds = playerCardIds,
            loungeStatus  = loungeStatus,
            cardCount     = cardCount,
        }
        if loungeStatus == LoungeStatus.Lock then
            local unlockType = vo.unlockType
            local unlockNum  = vo.unlockNum
            if unlockType > 0 then
                data.unlockDesc = GameUtils.GetUnlockDescr(unlockType, unlockNum)
            end
        end
        table.insert(loungeInfo, data)
        maxLoungeCount = maxLoungeCount + 1
    end
    table.sort(loungeInfo, function(a, b)
        return a.roomId < b.roomId
    end)

    ---------------------------------
    --- 初始化休息室 能使用的卡牌数据
    ---@type CardDojo[]
    local cards               = cardComp:GetAllCardTable()
    local t = {}
    local limitStatus2Status = MaidCoffeeUtils.GetMaidCoffeeCardStatusLimit(MaidCoffeeConstants.CafeStatus.Resting)
    ---过滤掉外卖中、在当店员的、在当店长的卡
    for i, v in ipairs(cards) do
        local cafeStatus = checkNumber(v.cafeStatus)
        if  
        -- not limitStatus2Status[cafeStatus]
        --     and self:CheckCardShowCond(v)
            MaidCoffeeUtils.CheckIsCanLoungeSelectCard(v, MaidCoffeeConstants.CafeStatus.Resting, limitStatus2Status)
        then
        --if true then
            v.cafeStatus = cafeStatus
            v.cafeEnergy = checkNumber(v.cafeEnergy)
            table.insert(t, v)
        end
    end
    self._cards                      = t
    self._loungeInfo                 = loungeInfo
    self._playerCardId2Info          = playerCardId2Info
    self._playerCardId2RecoveryValue = playerCardId2RecoveryValue
    self._maxLoungeCount             = maxLoungeCount
end

function OverManegeLoungeDataProvider:ParamsCards(cards)
    local playerCardIds = parse_strings(cards, ",")
    local cardCount     = self:FixCards(playerCardIds)
    return playerCardIds, cardCount
end

function OverManegeLoungeDataProvider:FixCards(playerCardIds)
    local cardCount     = 0
    for idx = 1, self._loungeCapacity do
        local playerCardId = checkNumber(playerCardIds[idx])
        if playerCardId > 0 then
            cardCount = cardCount + 1
        end
        playerCardIds[idx] = playerCardId
    end
    return cardCount
end

function OverManegeLoungeDataProvider:CreateLoungeCardData_(playerCardId, nextCureSeconds, touchTimes)
    ---@type CardDojo
    local cardDojo       = cardComp:GetCardById(playerCardId)
    local maxEnergy      = cardConfMgr:GetCardMoodByCardIdLevel(cardDojo.cardId, cardDojo.favorabilityLevel)
    local cafeEnergy     = checkNumber(cardDojo.cafeEnergy)

    --- 更新下卡牌现在的心情
    cardDojo:UpdateCardEnergy(cafeEnergy)

    ---休息室里的卡牌每X秒恢复一次心情值
    local recoveryInterval = self._recoveryInterval
    ---卡牌每分钟恢复心情值X点
    local recoverMoodValue = self._recoverMoodValue
    local leftSeconds = self:CalcLeftSeconds(maxEnergy, cafeEnergy, nextCureSeconds)
    local cardInfo = {
        playerCardId    = playerCardId,
        cardDojo        = cardDojo,
        cafeEnergy      = cafeEnergy,
        maxEnergy       = maxEnergy,
        touchTimes      = touchTimes,
        recoveryTime    = os.time() + leftSeconds
    }
    
    local recoveryValue = RecoveryValue(
            maxEnergy,
            cafeEnergy,
            recoveryInterval,
            recoverMoodValue,
            nextCureSeconds
    )
    return cardInfo, recoveryValue
end

function OverManegeLoungeDataProvider:CalcLeftSeconds(maxEnergy, cafeEnergy, nextRecoverSeconds)
    ---休息室里的卡牌每X秒恢复一次心情值
    local recoveryInterval = self._recoveryInterval
    ---卡牌每分钟恢复心情值X点
    local recoverMoodValue = self._recoverMoodValue
    local energy           = maxEnergy - cafeEnergy
    local leftSeconds = 0
    if energy > 0 then
        leftSeconds = math.floor(energy / recoverMoodValue) * recoveryInterval + nextRecoverSeconds
    end
    return leftSeconds
end

---CheckCardShowCond
---@param cardDojo CardDojo
function OverManegeLoungeDataProvider:CheckCardShowCond(cardDojo)
    local maxCardMood = cardConfMgr:GetCardMoodByCardIdLevel(cardDojo.cardId, cardDojo.favorabilityLevel)
    local cafeEnergy = checkNumber(cardDojo.cafeEnergy)
    
    return cafeEnergy < maxCardMood or
                    (checkNumber(cardDojo.cafeStatus) == MaidCoffeeConstants.CafeStatus.Resting)
    
end

function OverManegeLoungeDataProvider:StartTimer_()
    self:RemoveTimer_()
    if next(self._playerCardId2RecoveryValue) == nil then
        return
    end

    self._timer = CDTimerModule.GetInstance():AddCD(1, function(count, id)
        if count >= 0 then
            local playerCardId2Info = self._playerCardId2Info
            local recoveryValueCount = 0
            local isChange = false
            local hasChange = false
            --local isIgnoreCheck = self._isIgnoreCheck
            -- self._isIgnoreCheck = nil
            ---@param playerCardId number 卡牌id
            ---@param v Engine.Lib.RecoveryValue
            for playerCardId, v in pairs(self._playerCardId2RecoveryValue) do
                local info = playerCardId2Info[playerCardId]
                local oldCafeEnergy =  info.cafeEnergy
                v:UpdateTimeNow()
                local current = checkInt(v.Current)
                current = math.min(info.maxEnergy, current)
                --if not isIgnoreCheck then
                --    current = math.min(info.maxEnergy, current)
                --end

                isChange = oldCafeEnergy ~= current 
                hasChange = hasChange or isChange
                if isChange then
                    if info then
                        info.cafeEnergy = current
                        info.cardDojo:UpdateCardEnergy(current)
                    end
                end
                if current < info.maxEnergy then
                    recoveryValueCount = recoveryValueCount + 1
                end
            end
            
            Events.Broadcast(MaidCoffeeConstants.EventNames.LoungeCardEnergyTimeChange, hasChange)
            
            if recoveryValueCount == 0 then
                self:RemoveTimer_()
            end
            
        else
            self:RemoveTimer_()
        end
    end, 86400, false, true)
end
function OverManegeLoungeDataProvider:RemoveTimer_()
    local timer = self._timer
    if not isNull(timer) then
        CDTimerModule.GetInstance():RemoveCD(timer)
        self._timer = nil
    end
end


--endregion


--region logic

function OverManegeLoungeDataProvider:UpdateLounge(data)
    self:ClearLoungeCardStatus()
    self:InitCardsInfo(data)
    self:StartTimer_()

end

function OverManegeLoungeDataProvider:ClearLoungeCardStatus()
    --- 由于存在替换其他休息室的卡 这里直接清理所有在休息室中卡牌状态
    local playerCardId2Info = self._playerCardId2Info
    for playerCardId, value in pairs(playerCardId2Info) do
        ---@type CardDojo
        local cardDojo   = cardComp:GetCardById(playerCardId)
        cardDojo:UpdateCafeStatus(MaidCoffeeConstants.CafeStatus.Non)
    end
end

function OverManegeLoungeDataProvider:RemoveCardById(playerCardId)
    local cards = self:GetCards()
    for i = #cards, 1, -1 do
        ---@type CardDojo
        local v = cards[i]
        if checkNumber(v.id) == playerCardId then
            table.remove(cards, i)
            break
        end
        
    end
end

function OverManegeLoungeDataProvider:UpdateRecoveryValue(playerCardId, cafeEnergy, isIgnoreLimit, isIgnoreNotice)
    ---@type Engine.Lib.RecoveryValue
    local recoveryValue = self._playerCardId2RecoveryValue[playerCardId]
    if isNull(recoveryValue) then
        return
    end
    
    local info = self._playerCardId2Info[playerCardId]
    ---1. 取出下次恢复剩余时间
    local nextRecoverSeconds = (info.recoveryTime - os.time()) % self._recoveryInterval
    cafeEnergy = isIgnoreLimit and checkInt(cafeEnergy) or math.min(info.maxEnergy, checkInt(cafeEnergy)) 
    
    recoveryValue.Current = cafeEnergy
    recoveryValue:UpdateTimeNow()
    -- info.cafeEnergy = cafeEnergy
    -- info.cardDojo:UpdateCardEnergy(cafeEnergy,isIgnoreNotice)
    if cafeEnergy >= info.maxEnergy then
        info.recoveryTime = os.time()
    else
        local leftSeconds = self:CalcLeftSeconds(info.maxEnergy, cafeEnergy, nextRecoverSeconds)
        info.recoveryTime = os.time() + leftSeconds
    end
    -- self._playerCardId2Info[playerCardId] = info
end

function OverManegeLoungeDataProvider:UpdateTouchTimes(playerCardId, deltaTimes)
    local info = self._playerCardId2Info[playerCardId]
    if info == nil then
        return
    end
    info.touchTimes = deltaTimes + checkNumber(info.touchTimes) 
end

function OverManegeLoungeDataProvider:HandleLoungeSelectCardData(selectData, loungeIndex, roomId)
    local loungeData    = self:GetLoungeDataByIndex(loungeIndex)
    local playerCardIds = loungeData.playerCardIds
    local playerCardId2Index = {}
    for index, playerCardId in ipairs(playerCardIds) do
        if playerCardId > 0 then
            playerCardId2Index[playerCardId] = index
        else
            playerCardId2Index[playerCardId] = 0
        end
    end
    
    local isChange = false
    local cardIds = {}
    for index, value in ipairs(selectData) do
        if checkNumber(value.id) ~= checkNumber(playerCardIds[value.index]) then
            isChange = true
        end
        table.insert(cardIds, value.id)
    end

    if not isChange then return end

    self:RequestLoungeUpdate(roomId, cardIds)

end

