---GetLoungeCardStatus
---@param playerCardId number 卡牌id
---@return integer @ 1: 不在休息室 2：在休息室 3：满心情
function OverManegeLoungeDataProvider:GetLoungeCardStatus(playerCardId)
    if playerCardId == 0 then
        return 1
    end
    local info = self:GetCardInfoByPlayerCardId(playerCardId)
    if info == nil then
        return 1
    end

    local cafeEnergy = info.cafeEnergy
    local maxEnergy  = info.maxEnergy
    if cafeEnergy >= maxEnergy then
        return 3
    end
    
    return 2
end

function OverManegeLoungeDataProvider:GetLoungeIndexByCardId(cardId)
    for i, v in ipairs(self._loungeInfo) do
        for _, playerCardId in ipairs(v.playerCardIds) do
            if playerCardId == cardId then
                return i
            end
        end
    end
    return nil
end

---通过休息室下标获取休息室卡牌皮肤
---@param index number 休息室下标
function OverManegeLoungeDataProvider:GetLoungeCardSkinsByIndex(index)
    local loungeData = self:GetLoungeDataByIndex(index)
    local playerCardIds = loungeData.playerCardIds
    local t = {}
    for i, playerCardId in ipairs(playerCardIds) do
        table.insert(t, self:GetCardSkinByPlayerCardId(playerCardId))
    end
    return t
end

---GetCardSkinByPlayerCardId
---通过数据库id获取皮肤
---@param playerCardId number
function OverManegeLoungeDataProvider:GetCardSkinByPlayerCardId(playerCardId)
    local info = self:GetCardInfoByPlayerCardId(playerCardId)
    return info == nil and 0 or checkNumber(info.cardDojo.cardSkin)
end

---GetLoungeSelectCardInfoByIndex
---通过休息室下标获得选卡信息
function OverManegeLoungeDataProvider:GetLoungeSelectCardInfoByIndex(loungeIndex)
    local selectData = {}
    local loungeData = self:GetLoungeDataByIndex(loungeIndex)
    local playerCardIds = loungeData.playerCardIds
    for index, playerCardId in ipairs(playerCardIds) do
        table.insert(selectData, {index = index, id = playerCardId})
    end

    return selectData, loungeData.roomId
end
--endregion

--region check

function OverManegeLoungeDataProvider:CheckIsMaxEnergy(playerCardId)
    ---@type CardDojo
    local cardDojo  = cardComp:GetCardById(playerCardId)
    local maxEnergy = cardConfMgr:GetCardMoodByCardIdLevel(cardDojo.cardId, cardDojo.favorabilityLevel)
    return checkNumber(cardDojo.cafeEnergy) >= maxEnergy
end

---CheckSnackList
---检查食物列表
function OverManegeLoungeDataProvider:CheckSnackList()
    local snackList = self:GetSnackList()
    for i, v in ipairs(snackList) do
        if v.goodsNum > 0 then
            return true
        end
    end 
    return false
end

function OverManegeLoungeDataProvider:CheckRoomCardFeedCondition(loungeIndex)
    local loungeData = self:GetLoungeDataByIndex(loungeIndex)
    local playerCardIds = loungeData.playerCardIds
    for index, playerCardId in ipairs(playerCardIds) do
        -- print("playerCardId", playerCardId)
        if playerCardId > 0 and not self:CheckIsMaxEnergy(playerCardId) then
            return true
        end
    end
    return false
    
end

--endregion


return OverManegeLoungeDataProvider